INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das MVC-Pattern nur für Web-Apps geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Desktop-Apps nutzbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem MVC-Pattern?', 3, '[{"text": "Trennung von UI und Logik", "correct": true, "because": "Fördert Wartbarkeit"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "Hardwaresteuerung", "correct": false, "because": "Kein Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum MVC-Pattern?', 5, '[{"text": "Model", "correct": true, "because": "Verwaltet Daten und Logik"}, {"text": "View", "correct": true, "because": "Zeigt UI an"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Controller steuert die Logik. b) Das Model zeigt die UI.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Model ist Daten, View ist UI"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim MVC-Pattern?', 4, '[{"text": "Model-Logik", "correct": false, "because": "Kern der Datenverarbeitung"}, {"text": "View-Darstellung", "correct": false, "because": "Kern der UI"}, {"text": "Hardwareknoten", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob MVC auch ohne Controller funktioniert?', 2, '[{"text": "Nein", "correct": true, "because": "Controller verbindet Model und View"}, {"text": "Ja", "correct": false, "because": "Controller essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die View im MVC-Pattern?', 3, '[{"text": "Daten darstellen", "correct": true, "because": "Zeigt Model-Daten an"}, {"text": "Logik verarbeiten", "correct": false, "because": "Model-Aufgabe"}, {"text": "Eingaben steuern", "correct": false, "because": "Controller-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zum MVC-Pattern?', 5, '[{"text": "Controller", "correct": true, "because": "Verarbeitet Eingaben"}, {"text": "Model", "correct": true, "because": "Hält Daten und Logik"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) MVC trennt Verantwortlichkeiten. b) Es ist nur für kleine Apps geeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für große Apps"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das MVC-Pattern?', 4, '[{"text": "View", "correct": false, "because": "Zeigt UI an"}, {"text": "Controller", "correct": false, "because": "Steuert Interaktionen"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das MVC-Pattern nur für Webentwicklung?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Desktop und mehr"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehungen gibt es im MVC-Pattern?', 4, '[{"text": "Controller-Model", "correct": true, "because": "Logik aufrufen"}, {"text": "Model-View", "correct": true, "because": "Daten anzeigen"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass MVC die Wartung erschwert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Trennung erleichtert Wartung"}, {"text": "Ja", "correct": false, "because": "Entgegen dem Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim MVC-Pattern?', 3, '[{"text": "Trennung der Verantwortlichkeiten", "correct": true, "because": "Fördert Modularität"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Struktur zählt mehr"}, {"text": "Grafische Effekte", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Model enthält die Geschäftslogik. b) Die View steuert Eingaben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "View zeigt, Controller steuert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das MVC-Pattern?', 5, '[{"text": "Wartbarkeit", "correct": true, "because": "Trennung erleichtert Änderungen"}, {"text": "Wiederverwendbarkeit", "correct": true, "because": "Komponenten unabhängig"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "Hardwaresteuerung", "correct": false, "because": "Kein Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim MVC-Pattern unwichtig?', 3, '[{"text": "Model-View-Trennung", "correct": false, "because": "Kern des Patterns"}, {"text": "Controller-Logik", "correct": false, "because": "Steuert Interaktionen"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann das MVC-Pattern ohne View funktionieren?', 3, '[{"text": "Nein", "correct": true, "because": "View für Darstellung essenziell"}, {"text": "Ja", "correct": false, "because": "Trennung wäre unvollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob MVC für Tests nützlich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Komponenten einzeln testbar"}, {"text": "Nein", "correct": false, "because": "Fördert Testbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für die Datenverwaltung im MVC-Pattern?', 4, '[{"text": "Model", "correct": true, "because": "Hält Daten und Logik"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}, {"text": "UI-Komponente", "correct": false, "because": "View-Aufgabe"}]');
